<?php require_once __DIR__.'/../includes/functions.php';verify_csrf();$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$college=trim($_POST['college']??'');$course=trim($_POST['course']??'');$sem=filter_var($_POST['semester']??'',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>12]]);$pw=$_POST['password']??'';if(!$name||!$email||!$college||!$course||!$sem||strlen($pw)<8||$pw!==($_POST['confirm']??'')){flash('danger','Please complete each field and use matching passwords of at least 8 characters.');go('../register.php');}try{$pdo=db();$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO student_profiles(user_id,college,course,semester) VALUES(?,?,?,?)')->execute([$id,$college,$course,$sem]);$pdo->commit();session_regenerate_id(true);$_SESSION['uid']=$id;flash('success','Welcome to StudySync. Add your learning goals to strengthen your profile.');go('../student/edit-profile.php');}catch(PDOException $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getCode()==='23000'?'An account already uses that email.':'We could not create your account. Please try again.');go('../register.php');}
